#include "screen_model.h"
#include "game_script.h"
#include <QPainter>
namespace cf {
ScreenBitmap screenBitmap(const QImage &image,bool dmg,int base){ImportOptions opts;opts.screen=true;opts.width=160;opts.height=144;opts.fit=ImportOptions::Stretch;auto a=convertImage(image,opts);auto data=a.tileData(dmg);ScreenBitmap b;b.palette=a.palette;if(dmg){auto order=a.colorOrder(true);QVector<quint16> palette;for(int i:order)palette<<a.palette[i];b.palette=palette;}QVector<QByteArray> unique;for(int i=0;i<360;++i){auto tile=data.mid(i*16,16);int n=unique.indexOf(tile);if(n<0){n=unique.size();unique<<tile;b.tiles+=tile;}b.map+=char(base+n);}return b;}
QImage sceneBackdrop(const Project &p,const Scene &s){QImage image(160,144,QImage::Format_RGB32);image.fill(rgb555(s.background));QPainter painter(&image);for(auto &e:s.elements)if(e.type=="image")if(auto a=p.asset(e.image))painter.drawImage(QRect(e.rect.x()*8,e.rect.y()*8,e.rect.width()*8,e.rect.height()*8),a->image(p.target=="gb"));return image;}
QImage sceneImage(const Project &p,const Scene &s,const CFGameState *state,int selected){auto image=sceneBackdrop(p,s);QStringList lines;for(int y=0;y<18;++y)lines<<QString(20,' ');QByteArray covered(360,0);auto put=[&](int x,int y,QChar c){if(x>=0&&x<20&&y>=0&&y<18){lines[y][x]=c;covered[y*20+x]=1;}};CFGameState initial{};CFGameDef d{};if(!state){for(int i=0;i<p.variables.size();++i)initial.variables[i]=p.variables[i].initial;state=&initial;}for(int i=0;i<s.elements.size();++i){auto &e=s.elements[i];auto r=e.rect;if(e.type=="image")continue;if(e.type=="panel"){for(int y=0;y<r.height();++y)for(int x=0;x<r.width();++x)put(r.x()+x,r.y()+y,(x==0||x==r.width()-1)?((y==0||y==r.height()-1)?'+':'|'):(y==0||y==r.height()-1)?'-':' ');continue;}auto text=renderGameText(p,*state,e.text,qMax(1,r.width()-(e.type=="button"?1:0))).split('\n');for(int y=0;y<r.height();++y)for(int x=0;x<r.width();++x)put(r.x()+x,r.y()+y,' ');bool button=e.type=="button";int cols=r.width()-(button?1:0);for(int y=0;y<qMin(r.height(),int(text.size()));++y){int offset=e.align==1?(cols-text[y].size())/2:e.align==2?cols-text[y].size():0;for(int x=0;x<text[y].size();++x)put(r.x()+(button?1:0)+qMax(0,offset)+x,r.y()+y,text[y][x]);}if(button){CFCondition c{};QString error;bool ok=GameCompiler(p).condition(e.condition,c,error)&&cf_game_condition(state,&c);put(r.x(),r.y(),ok?(i==selected?'>':' '):'x');}}
QPainter painter(&image);auto font=textScreenImage(lines,{0,0,20,18},p.target=="gb");for(int y=0;y<18;++y)for(int x=0;x<20;++x)if(covered[y*20+x])painter.drawImage(QRect(x*8,y*8,8,8),font,QRect(x*8,y*8,8,8));return image;}
}
